## Sample code
```kotlin
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TestSheet(
    onDismissRequest: () -> Unit
) {
    AdaptiveBottomSheet(
        adaptiveSheetState = rememberAdaptiveSheetState(skipPartiallyExpanded = true),
        dragHandle = null,
        onDismissRequest = onDismissRequest
    ) {
        LazyColumn(
            modifier = Modifier.fillMaxSize()
        ) {
            items(100) {
                Text(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp),
                    text = "${it.inc()}"
                )
            }
        }
    }
}
```

